{"command": "mkdir -p /workspace/work && cd /workspace/cms && python3 - <<'EOF'
import sqlite3, os
con = sqlite3.connect('ridgeline_cms.db')
con.row_factory = sqlite3.Row
for n in range(1001,1013):
    cid = f'RIG-2026-{n}'
    out = []
    for row in con.execute("select * from cases where case_id=?", (cid,)):
        out.append('CASE: ' + str(dict(row)))
    for row in con.execute("select * from subjects where case_id=?", (cid,)):
        out.append('SUBJECT: ' + str(dict(row)))
        sid = row['subject_id']
        for t in ['address_history','phones','vehicles','employment','social_media']:
            for r in con.execute(f"select * from {t} where subject_id=? order by 1", (sid,)):
                out.append(f'{t.upper()}: ' + str(dict(r)))
    for row in con.execute("select * from notes where case_id=? order by date", (cid,)):
        out.append('NOTE [' + row['date'] + '] ' + row['author'] + ': ' + row['note'])
    for row in con.execute("select * from field_logs where case_id=? order by date", (cid,)):
        out.append(f"LOG [{row['date']} {row['time']}] {row['investigator']}: {row['observation']}")
    open(f'/workspace/work/{cid}.txt','w').write('\n'.join(out))
    print(cid, len(out), 'lines')
EOF"}

